(6910440, 1041955, 119012, '<td valign="top">beautiful, my favorite so far.</td>', 'beautiful, my favorite so far.', '2012-11-21 07:02:52.000000', NULL, 1),
(6910491, 1041546, 10785, '<td valign="top">This is a wonderful portrait but not a real good example of high contrast in my opinion. This is very diffuse lighting creating an even contrast throughout the photo on the subject. A better example would have been to have her stand out in full sun.</td>', 'This is a wonderful portrait but not a real good example of high contrast in my opinion. This is very diffuse lighting creating an even contrast throughout the photo on the subject. A better example would have been to have her stand out in full sun.', '2012-11-21 08:20:22.000000', NULL, 1),
