(6910714, 1041909, 114225, '<td valign="top">I like the way the shadows create a gradient of contrast.</td>', 'I like the way the shadows create a gradient of contrast.', '2012-11-21 12:53:23.000000', NULL, 1),
(6910715, 1041510, 114225, '<td valign="top">I enjoy this. The centered (vertically) horizon normalyl isn''t attractive, but in this it works.</td>', 'I enjoy this. The centered (vertically) horizon normalyl isn''t attractive, but in this it works.', '2012-11-21 12:54:48.000000', NULL, 1),
(6910717, 1041832, 114225, '<td valign="top">Looks very tasty indeed.<br/>I think a couple very minor things may improve this further: wiping up that drop of liquid, getting rid of the white spot in the lower left, not having shadows cast in the background.</td>', 'Looks very tasty indeed.I think a couple very minor things may improve this further: wiping up that drop of liquid, getting rid of the white spot in the lower left, not having shadows cast in the background.', '2012-11-21 12:57:09.000000', NULL, 1),
