INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6910721, 1041645, 114225, '<td valign="top">Gorgeous image. The streams of light cutting through the fog is always great.</td>', 'Gorgeous image. The streams of light cutting through the fog is always great.', '2012-11-21 12:58:53.000000', NULL, 1),
(6910727, 1041546, 114225, '<td valign="top">Overall a nice portrait with good contrast. Her facial expression isn''t very appealing to me, as she looks a bit dis-interested.</td>', 'Overall a nice portrait with good contrast. Her facial expression isn''t very appealing to me, as she looks a bit dis-interested.', '2012-11-21 13:05:46.000000', NULL, 1),
(6910728, 1041756, 114225, '<td valign="top">Nice use of perspective. The people add a TON to the composition.</td>', 'Nice use of perspective. The people add a TON to the composition.', '2012-11-21 13:06:24.000000', NULL, 1),
(6910729, 1041823, 114225, '<td valign="top">I like the composition and the light...except for the shadow by the eyes. I wish I could see the eyes better.</td>', 'I like the composition and the light...except for the shadow by the eyes. I wish I could see the eyes better.', '2012-11-21 13:08:59.000000', NULL, 1),
(6910732, 1041929, 114225, '<td valign="top">An overall fine photo. Seems you used some vignetted to enhance the illusion of contrast. I wonder if instead you burned the background if that would better portray contrast.</td>', 'An overall fine photo. Seems you used some vignetted to enhance the illusion of contrast. I wonder if instead you burned the background if that would better portray contrast.', '2012-11-21 13:12:00.000000', NULL, 1),
(6910733, 1042025, 114225, '<td valign="top">Very nice. I really enjoy the details in the frames.</td>', 'Very nice. I really enjoy the details in the frames.', '2012-11-21 13:12:29.000000', NULL, 1),
(6910734, 1041786, 114225, '<td valign="top">Lines and basic shapes can make for interesting photos.</td>', 'Lines and basic shapes can make for interesting photos.', '2012-11-21 13:13:00.000000', NULL, 1),
(6910736, 1041706, 114225, '<td valign="top">I really enjoy the contre-jour style employed here.</td>', 'I really enjoy the contre-jour style employed here.', '2012-11-21 13:14:52.000000', NULL, 1),
(6910737, 1041910, 114225, '<td valign="top">I wee what you were going for here, and I do like the thought. But overall, I think that breaking up their legs causes a distraction in the image.</td>', 'I wee what you were going for here, and I do like the thought. But overall, I think that breaking up their legs causes a distraction in the image.', '2012-11-21 13:16:29.000000', NULL, 1),
(6910738, 1042015, 114225, '<td valign="top">A serene setting, and does have some contrast due to the sun in the scene. I don''t think the contrast overall is very high.</td>', 'A serene setting, and does have some contrast due to the sun in the scene. I don''t think the contrast overall is very high.', '2012-11-21 13:19:15.000000', NULL, 1),
(6910739, 1042005, 114225, '<td valign="top">Nice fine. The deep shadows contain a mystery I would like to explore.</td>', 'Nice fine. The deep shadows contain a mystery I would like to explore.', '2012-11-21 13:19:52.000000', NULL, 1),
