(6912088, 1041823, 23484, '<td valign="top">Great job on the softness.</td>', 'Great job on the softness.', '2012-11-23 18:08:51.000000', NULL, 1),
(6912089, 1041720, 23484, '<td valign="top">Very nice horizontal portrait.</td>', 'Very nice horizontal portrait.', '2012-11-23 18:09:37.000000', NULL, 1),
(6912090, 1041801, 23484, '<td valign="top">Very interesting shot.</td>', 'Very interesting shot.', '2012-11-23 18:10:23.000000', NULL, 1),
(6912091, 1041772, 23484, '<td valign="top">Outstanding catch.</td>', 'Outstanding catch.', '2012-11-23 18:10:54.000000', NULL, 1),
(6912093, 1041679, 23484, '<td valign="top">Excellent composition.</td>', 'Excellent composition.', '2012-11-23 18:11:14.000000', NULL, 1),
