(6912192, 1041884, 30982, '<td valign="top">There''s a wonderful sense of peace to this.  Nicely done.<br/><br/><i>Message edited by author 2012-11-28 00:09:24.</i></td>', 'There''s a wonderful sense of peace to this.  Nicely done.', '2012-11-23 21:37:39.000000', '2012-11-28 00:09:24.000000', 1),
