(6912198, 1041803, 30982, '<td valign="top">Yuck.  But well done!</td>', 'Yuck.  But well done!', '2012-11-23 21:39:00.000000', NULL, 1),
(6912199, 1041870, 30982, '<td valign="top">Some mighty expressive eyes on that young lady!</td>', 'Some mighty expressive eyes on that young lady!', '2012-11-23 21:39:14.000000', NULL, 1),
