(6912204, 1041992, 30982, '<td valign="top">LOVE the grain.</td>', 'LOVE the grain.', '2012-11-23 21:40:00.000000', NULL, 1),
(6912205, 1041379, 30982, '<td valign="top">A very engaging portrait!</td>', 'A very engaging portrait!', '2012-11-23 21:40:28.000000', NULL, 1),
