(6913931, 1041685, 155989, '<td valign="top">If this is of the 5 senses then you left off hearing, but as is, I love it. Subtle. Excellent use of high contrast to highlight the necessary.</td>', 'If this is of the 5 senses then you left off hearing, but as is, I love it. Subtle. Excellent use of high contrast to highlight the necessary.', '2012-11-27 04:57:41.000000', NULL, 1),
(6913934, 1041793, 155989, '<td valign="top">Interesting idea but I feel the composition doesn''t really work that well. The jarring elements are the problems with focus (should be either all soft focus or more of the elements should be in focus) I think the mono conversion should be have been stronger/starker and the juxtaposition of the background and foreground images should have been better composed.</td>', 'Interesting idea but I feel the composition doesn''t really work that well. The jarring elements are the problems with focus (should be either all soft focus or more of the elements should be in focus) I think the mono conversion should be have been stronger/starker and the juxtaposition of the background and foreground images should have been better composed.', '2012-11-27 05:05:04.000000', NULL, 1),
(6913935, 1041964, 155989, '<td valign="top">Excellent subject for high contrast being a stark and ''high contrast'' landscape.</td>', 'Excellent subject for high contrast being a stark and ''high contrast'' landscape.', '2012-11-27 05:06:04.000000', NULL, 1),
(6913938, 1041916, 126903, '<td valign="top">Soo funny..</td>', 'Soo funny..', '2012-11-27 05:26:50.000000', NULL, 1),
